function getCvssData(cve) {
  const metrics = cve?.metrics || {};

  if (metrics.cvssMetricV31 && metrics.cvssMetricV31.length > 0) {
    const metric = metrics.cvssMetricV31[0];
    return {
      cvss_version: "3.1",
      cvss_source: metric.source || "NVD",
      cvss_base_score: metric.cvssData?.baseScore ?? 0,
      cvss_base_severity: metric.cvssData?.baseSeverity || "N/A",
      vector_string: metric.cvssData?.vectorString || "N/A",
      exploitability_score: metric.exploitabilityScore ?? null,
      impact_score: metric.impactScore ?? null
    };
  }

  if (metrics.cvssMetricV30 && metrics.cvssMetricV30.length > 0) {
    const metric = metrics.cvssMetricV30[0];
    return {
      cvss_version: "3.0",
      cvss_source: metric.source || "NVD",
      cvss_base_score: metric.cvssData?.baseScore ?? 0,
      cvss_base_severity: metric.cvssData?.baseSeverity || "N/A",
      vector_string: metric.cvssData?.vectorString || "N/A",
      exploitability_score: metric.exploitabilityScore ?? null,
      impact_score: metric.impactScore ?? null
    };
  }

  if (metrics.cvssMetricV2 && metrics.cvssMetricV2.length > 0) {
    const metric = metrics.cvssMetricV2[0];
    return {
      cvss_version: "2.0",
      cvss_source: metric.source || "NVD",
      cvss_base_score: metric.cvssData?.baseScore ?? 0,
      cvss_base_severity: metric.baseSeverity || "N/A",
      vector_string: metric.cvssData?.vectorString || "N/A",
      exploitability_score: metric.exploitabilityScore ?? null,
      impact_score: metric.impactScore ?? null
    };
  }

  return {
    cvss_version: "N/A",
    cvss_source: "N/A",
    cvss_base_score: 0,
    cvss_base_severity: "N/A",
    vector_string: "N/A",
    exploitability_score: null,
    impact_score: null
  };
}

function extractAttackVector(vectorString) {
  if (!vectorString || vectorString === "N/A") return "N/A";

  const match = vectorString.match(/AV:([NALP])/);
  if (!match) return "N/A";

  const map = {
    N: "NETWORK",
    A: "ADJACENT",
    L: "LOCAL",
    P: "PHYSICAL"
  };

  return map[match[1]] || "N/A";
}

function extractCvssMetric(vectorString, metricCode) {
  if (!vectorString || vectorString === "N/A") return "N/A";

  const regex = new RegExp(`${metricCode}:([^/]+)`);
  const match = vectorString.match(regex);

  return match ? match[1] : "N/A";
}

function getDescription(cve) {
  const descriptions = cve?.descriptions || [];
  const english = descriptions.find(d => d.lang === "en");
  return english?.value || "No English description available.";
}

function getReferenceUrls(cve) {
  const references = cve?.references?.referenceData || cve?.references || [];

  if (!Array.isArray(references)) {
    return [];
  }

  return references
    .map(ref => ref.url)
    .filter(Boolean)
    .slice(0, 5);
}

function getWeaknesses(cve) {
  const weaknesses = cve?.weaknesses || [];
  const cwes = [];

  for (const weakness of weaknesses) {
    const descriptions = weakness.description || [];
    for (const desc of descriptions) {
      if (desc.value) {
        cwes.push(desc.value);
      }
    }
  }

  return [...new Set(cwes)];
}

// Procesa TODOS los items que llegan del Merge
const mergedItems = $input.all();

const rows = [];

for (const item of mergedItems) {
  const merged = item.json;
  const vulnerabilities = merged.vulnerabilities || [];

  // Campos contextuales del activo.
  // Se anaden aqui para que viajen en la tabla maestra Asset-CVE
  // y esten disponibles posteriormente en el nodo de scoring (08).
  // IMPORTANTE: deben incluirse los valores _norm y el flag de override,
  // o el nodo 08 los recibira como undefined y los tratara como 0.
  const assetContext = {
    exposure: merged.exposure,
    exposure_norm: merged.exposure_norm ?? null,

    criticality: merged.criticality,
    criticality_norm: merged.criticality_norm ?? null,
    criticality_overridden: merged.criticality_overridden === true,
    criticality_override_level: merged.criticality_override_level ?? null,

    module_id: merged.module_id ?? null,
    module_name: merged.module_name ?? null,
    module_sensitivity: merged.module_sensitivity ?? null,
    module_sensitivity_norm: merged.module_sensitivity_norm ?? null,

    blast_radius_score: merged.blast_radius_score ?? 0,
    blast_radius_norm: merged.blast_radius_norm ?? null,
    blast_radius_status: merged.blast_radius_status ?? "pending"
  };

  // Caso: NVD no devuelve vulnerabilidades
  if (vulnerabilities.length === 0) {
    rows.push({
      json: {
        asset_id: merged.asset_id,
        asset_name: merged.asset_name,
        asset_type: merged.asset_type,
        software: merged.software,
        asset_version: merged.asset_version,
        cpe_name: merged.cpe_name,

        // Contexto del activo
        ...assetContext,

        cve_id: "NO_CVE_FOUND",
        cve_published: null,
        cve_last_modified: null,
        vuln_status: "NO_CVE_FOUND",
        nvd_description: `No CVEs found in NVD for CPE ${merged.cpe_name}`,
        nvd_references: [],
        weaknesses: [],

        cvss_version: "N/A",
        cvss_source: "N/A",
        cvss_base_score: 0,
        cvss_base_severity: "N/A",
        cvss_normalized: 0,
        vector_string: "N/A",
        exploitability_score: null,
        impact_score: null,

        attack_vector: "N/A",
        attack_complexity: "N/A",
        privileges_required: "N/A",
        user_interaction: "N/A",
        scope: "N/A",
        confidentiality_impact: "N/A",
        integrity_impact: "N/A",
        availability_impact: "N/A",

        epss_score: null,
        epss_percentile: null,
        kev_flag: false,
        kev_date_added: null,
        kev_due_date: null,
        kev_known_ransomware: null,

        technical_risk: null,
        risk_score: null,
        risk_level: "INFO",
        risk_rationale: `NVD no devolvio vulnerabilidades para ${merged.asset_name}.`,

        source: "NVD",
        pipeline_stage: "asset_master_table",
        created_at: new Date().toISOString()
      }
    });

    continue;
  }

  // Caso normal: una fila por cada CVE del activo
  for (const vulnWrapper of vulnerabilities) {
    const cve = vulnWrapper.cve;
    if (!cve) continue;

    const cvss = getCvssData(cve);
    const attackVector = extractAttackVector(cvss.vector_string);

    const cvssNormalized = cvss.cvss_base_score
      ? Number((cvss.cvss_base_score / 10).toFixed(2))
      : 0;

    rows.push({
      json: {
        // Datos del activo
        asset_id: merged.asset_id,
        asset_name: merged.asset_name,
        asset_type: merged.asset_type,
        software: merged.software,
        asset_version: merged.asset_version,
        cpe_name: merged.cpe_name,

        // Contexto del activo
        ...assetContext,

        // Datos de la CVE/NVD
        cve_id: cve.id,
        cve_published: cve.published || null,
        cve_last_modified: cve.lastModified || null,
        vuln_status: cve.vulnStatus || "N/A",
        nvd_description: getDescription(cve),
        nvd_references: getReferenceUrls(cve),
        weaknesses: getWeaknesses(cve),

        // Datos CVSS
        cvss_version: cvss.cvss_version,
        cvss_source: cvss.cvss_source,
        cvss_base_score: cvss.cvss_base_score,
        cvss_base_severity: cvss.cvss_base_severity,
        cvss_normalized: cvssNormalized,
        vector_string: cvss.vector_string,
        exploitability_score: cvss.exploitability_score,
        impact_score: cvss.impact_score,

        // Vector CVSS parseado
        attack_vector: attackVector,
        attack_complexity: extractCvssMetric(cvss.vector_string, "AC"),
        privileges_required: extractCvssMetric(cvss.vector_string, "PR"),
        user_interaction: extractCvssMetric(cvss.vector_string, "UI"),
        scope: extractCvssMetric(cvss.vector_string, "S"),
        confidentiality_impact: extractCvssMetric(cvss.vector_string, "C"),
        integrity_impact: extractCvssMetric(cvss.vector_string, "I"),
        availability_impact: extractCvssMetric(cvss.vector_string, "A"),

        // Campos preparados para enriquecimiento posterior
        epss_score: null,
        epss_percentile: null,
        kev_flag: false,
        kev_date_added: null,
        kev_due_date: null,
        kev_known_ransomware: null,

        // Campos preparados para scoring
        technical_risk: null,
        risk_score: null,
        risk_level: null,
        risk_rationale: null,

        // Metadatos
        source: "NVD",
        pipeline_stage: "asset_master_table",
        created_at: new Date().toISOString()
      }
    });
  }
}

return rows;

// ============================================================================
// NODO 01c - NORMALIZE ASSETS
// ----------------------------------------------------------------------------
// Deriva las magnitudes normalizadas del ContextFactor para cada activo.
//
// Reparto de responsabilidades por naturaleza de cada dimensión:
//   - CPE y exposure  -> DECLARADOS en el activo (propiedad del activo).
//                        Aquí solo se normaliza la exposición.
//   - module_sensitivity -> DERIVADA del módulo (propiedad del módulo).
//   - criticality     -> DEFAULT del módulo/subgrupo + OVERRIDE del analista.
//   - blast_radius    -> CALCULADO dinámicamente desde la matriz de alcance
//                        sobre los módulos PRESENTES en el inventario.
// ============================================================================

// ---------------------------------------------------------------------------
// MAPAS DE ESCALA (1-5) -> normalización /5
// ---------------------------------------------------------------------------
const exposureMap = {
  isolated: 1,
  restricted_internal: 2,
  internal: 3,
  dmz: 4,
  internet: 5
};

// Nombre por módulo padre (para descripción)
const moduleNameMap = {
  B01: "Perímetro web",
  B02: "Aplicación",
  B03: "Datos relacionales",
  B04: "Identidad corporativa",
  B05: "Conectividad segura",
  B06: "SDN / microsegmentación",
  B07: "Cloud compute",
  B08: "Cloud storage",
  B09: "Cloud identidad",
  B10: "Contenedores",
  B11: "OT / Industrial",
  B12: "Endpoints"
};

// Sensibilidad por sub-código (propiedad del módulo). Sin cambios.
const moduleSensitivityMap = {
  "B01": 4,
  "B02.1": 3, "B02.2": 4,
  "B03.1": 4, "B03.2": 5,
  "B04": 5,
  "B05": 5,
  "B06.1": 4, "B06.2": 5,
  "B07": 4,
  "B08.1": 4, "B08.2": 5,
  "B09": 5,
  "B10.1": 4, "B10.2": 5,
  "B11": 4,
  "B12.1": 3, "B12.2": 4, "B12.3": 5
};

// ---------------------------------------------------------------------------
// CRITICIDAD POR DEFECTO (por sub-código; escala 1-5).
// Es el valor de partida asociado al módulo/subgrupo. Se AJUSTA por activo
// mediante override (que activa H=1). Escala: Bajo=2, Medio=3, Alto=4, Crítico=5.
// (negligible=1 se reserva por completitud de la escala.)
// ---------------------------------------------------------------------------
const criticalityDefaultMap = {
  "B01": 4,                       // Alto
  "B02.1": 3, "B02.2": 4,         // Medio / Alto
  "B03.1": 3, "B03.2": 4,         // Medio / Alto
  "B04": 5,                       // Crítico
  "B05": 4,                       // Alto
  "B06.1": 3, "B06.2": 3,         // Medio / Medio
  "B07": 3,                       // Medio
  "B08.1": 3, "B08.2": 4,         // Medio / Alto
  "B09": 5,                       // Crítico
  "B10.1": 3, "B10.2": 3,         // Medio / Medio
  "B11": 3,                       // Medio (PLC/CAM se ajustan por override)
  "B12.1": 2, "B12.2": 3, "B12.3": 4  // Bajo / Medio / Alto
};

// Mapa de nivel textual de override -> valor 1-5 (para criticality_override_level)
const criticalityLevelMap = {
  negligible: 1,
  low: 2,
  medium: 3,
  high: 4,
  critical: 5
};

// ---------------------------------------------------------------------------
// MATRIZ DE ALCANCE DIRECTO (incluye el propio módulo).
// Cada entrada lista los módulos alcanzables DIRECTAMENTE desde el módulo clave.
// El blast radius se calcula sobre los módulos realmente PRESENTES.
// ---------------------------------------------------------------------------
const reachMatrix = {
  B01: ["B01", "B02"],
  B02: ["B02", "B03", "B04", "B08", "B09"],
  B03: ["B03"],
  B04: ["B01", "B02", "B03", "B04", "B09", "B12"],
  B05: ["B01", "B02", "B03", "B04", "B05", "B06", "B07", "B08", "B10", "B11", "B12"],
  B06: ["B01", "B02", "B03", "B04", "B05", "B06", "B07", "B08", "B10", "B11", "B12"],
  B07: ["B07", "B08", "B09", "B10"],
  B08: ["B08"],
  B09: ["B02", "B04", "B07", "B08", "B09", "B10", "B12"],
  B10: ["B02", "B07", "B08", "B09", "B10"],
  B11: ["B11"],
  B12: ["B02", "B04", "B07", "B09", "B12"]
};

// Pesos de propagación por profundidad
const WEIGHT_DIRECT = 1.0;   // alcance directo
const WEIGHT_ONEHOP = 0.5;   // alcance a un salto

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------
const moduleParent = (mid) => (mid || "").split(".")[0];

/**
 * Calcula el blast_radius_norm de un módulo dado el conjunto de módulos presentes.
 *   numerador = (# directos presentes) * 1.0 + (# a-un-salto presentes, vía
 *               intermediario presente, excluyendo los ya directos) * 0.5
 *   blast_radius_norm = numerador / N   (N = nº de módulos presentes)
 * Cada módulo se alcanza a sí mismo (incluido en reachMatrix), garantizando un
 * radio estrictamente positivo.
 */
function computeBlastRadius(mod, presentSet, N) {
  const neighbors = reachMatrix[mod] || [mod];
  const direct = neighbors.filter((m) => presentSet.has(m));
  const directSet = new Set(direct);

  const oneHop = new Set();
  for (const inter of direct) {
    const interNeighbors = reachMatrix[inter] || [];
    for (const m of interNeighbors) {
      if (presentSet.has(m) && !directSet.has(m)) {
        oneHop.add(m);
      }
    }
  }

  const numerator = direct.length * WEIGHT_DIRECT + oneHop.size * WEIGHT_ONEHOP;
  return Number((numerator / N).toFixed(4));
}

// ===========================================================================
// PROCESAMIENTO
// ===========================================================================

// --- Paso 1: determinar los módulos PRESENTES en el inventario (visión global) ---
const presentModules = new Set(
  items.map((it) => moduleParent(it.json.module_id)).filter(Boolean)
);
const N = presentModules.size;

// --- Paso 2: precalcular el blast radius de cada módulo presente (una vez) ---
const blastRadiusByModule = {};
for (const mod of presentModules) {
  blastRadiusByModule[mod] = computeBlastRadius(mod, presentModules, N);
}

// --- Paso 3: normalizar cada activo ---
return items.map((item) => {
  const a = item.json;

  // Exposición (declarada en el activo -> solo se normaliza)
  const exposureScore = exposureMap[a.exposure] ?? null;

  // Módulo
  const parent = moduleParent(a.module_id);
  const moduleName = moduleNameMap[parent] ?? "Unknown";

  // Sensibilidad de módulo (derivada)
  const moduleSensitivity = moduleSensitivityMap[a.module_id] ?? null;

  // --- Criticidad: default de módulo, salvo override del analista ---
  const isOverridden = a.criticality_overridden === true;
  let criticalityScore;
  let criticalitySource;
  if (isOverridden) {
    // El analista fijó el nivel en criticality_override_level (low/high/...)
    criticalityScore = criticalityLevelMap[a.criticality_override_level] ?? null;
    criticalitySource = "override";
  } else {
    // Valor por defecto del módulo/subgrupo
    criticalityScore = criticalityDefaultMap[a.module_id]
                    ?? criticalityDefaultMap[parent]
                    ?? null;
    criticalitySource = "default";
  }
  const criticalityNorm =
    criticalityScore !== null ? Number((criticalityScore / 5).toFixed(4)) : null;

  // Flag H: 1 cuando hay override de criticidad
  const hFlag = isOverridden ? 1 : 0;

  // --- Blast radius: calculado desde la matriz sobre módulos presentes ---
  const blastRadiusNorm = blastRadiusByModule[parent] ?? null;

  return {
    json: {
      ...a,

      // Exposición
      exposure_score: exposureScore,
      exposure_norm: exposureScore !== null
        ? Number((exposureScore / 5).toFixed(4)) : null,

      // Criticidad
      criticality_score: criticalityScore,
      criticality_norm: criticalityNorm,
      criticality_source: criticalitySource,   // "default" | "override"
      h_flag: hFlag,

      // Módulo
      module_id: a.module_id,
      module_parent: parent,
      module_name: moduleName,

      // Sensibilidad
      module_sensitivity: moduleSensitivity,
      module_sensitivity_norm: moduleSensitivity !== null
        ? Number((moduleSensitivity / 5).toFixed(4)) : null,

      // Blast radius (calculado dinámicamente)
      blast_radius_norm: blastRadiusNorm,
      blast_radius_modules_present: N   // trazabilidad: N usado en el cálculo
    }
  };
});

// ============================================================
// 07 - Calculate CVE Technical Risk
// Calcula SOLO el riesgo técnico de cada CVE (por par activo-CVE).
//   TechnicalRisk = 0.40*CVSS_norm + 0.35*EPSS_norm + 0.25*KEV_flag
//
// El contexto (ContextFactor, override H) y el FinalRisk NO se calculan
// aquí: son propiedad del ACTIVO y se aplican en el nodo 08, sobre la
// CVE de mayor TechnicalRisk. Este nodo arrastra el contexto del activo
// intacto para que el 08 lo tenga disponible.
// ============================================================

function clamp(value, min = 0, max = 1) {
  const num = Number(value);
  if (!Number.isFinite(num)) return min;
  return Math.min(Math.max(num, min), max);
}

function normalizeCvss(cvss) {
  const value = Number(cvss ?? 0);
  return clamp(value / 10);
}

function normalizeEpss(epss) {
  const value = Number(epss ?? 0);
  if (value > 1) {
    return clamp(value / 100);
  }
  return clamp(value);
}

function normalizeKev(kevFlag) {
  if (kevFlag === true) return 1;
  if (kevFlag === false) return 0;
  const value = String(kevFlag ?? "").toLowerCase().trim();
  if (["true", "yes", "y", "1", "kev"].includes(value)) {
    return 1;
  }
  return 0;
}

const inputItems = $input.all();
const output = [];

for (const item of inputItems) {
  const row = item.json;

  // Caso: activo sin CVEs -> technical risk 0, se arrastra el contexto
  if (row.cve_id === "NO_CVE_FOUND") {
    output.push({
      json: {
        ...row,
        cvss_norm: 0,
        epss_norm: 0,
        kev_flag: false,
        kev_norm: 0,
        technical_risk: 0,
        technical_risk_level: "INFO",
        scoring_model: "technical_risk_v4",
        scoring_formula: "TechnicalRisk = 0.40*CVSS_norm + 0.35*EPSS_norm + 0.25*KEV_flag",
        pipeline_stage: "cve_technical_risk",
        technical_risk_at: new Date().toISOString()
      }
    });
    continue;
  }

  // --- Normalización de los tres componentes técnicos ---
  const cvss = Number(row.cvss_base_score ?? row.cvss_score ?? 0);
  const epssScore = Number(row.epss_score ?? 0);

  const cvssNorm = Number(
    row.cvss_norm ??
    row.cvss_normalized ??
    normalizeCvss(cvss)
  );
  const epssNorm = Number(
    row.epss_norm ??
    normalizeEpss(epssScore)
  );
  const kevNorm = normalizeKev(row.kev_flag);

  // --- TechnicalRisk (único cálculo de este nodo) ---
  const technicalRisk =
    (0.40 * cvssNorm) +
    (0.35 * epssNorm) +
    (0.25 * kevNorm);

  const technicalRiskRounded = Number(technicalRisk.toFixed(4));

  output.push({
    json: {
      ...row,

      // Componentes técnicos normalizados
      cvss_score: cvss,
      cvss_norm: Number(cvssNorm.toFixed(4)),
      epss_score: epssScore,
      epss_norm: Number(epssNorm.toFixed(4)),
      kev_flag: kevNorm === 1,
      kev_norm: kevNorm,

      // Componentes ponderados (auditoría)
      cvss_component: Number((0.40 * cvssNorm).toFixed(4)),
      epss_component: Number((0.35 * epssNorm).toFixed(4)),
      kev_component: Number((0.25 * kevNorm).toFixed(4)),

      // Resultado: riesgo técnico de la CVE
      technical_risk: technicalRiskRounded,

      // Contexto del activo: se arrastra INTACTO para el nodo 08.
      // NO se aplica aquí (el contexto pertenece al activo, no a la CVE).
      // exposure_norm, criticality_norm, module_sensitivity_norm,
      // blast_radius_norm, criticality_overridden ya viajan en ...row

      scoring_model: "technical_risk_v4",
      scoring_formula: "TechnicalRisk = 0.40*CVSS_norm + 0.35*EPSS_norm + 0.25*KEV_flag",

      pipeline_stage: "cve_technical_risk",
      technical_risk_at: new Date().toISOString()
    }
  });
}

return output;

// ============================================================
// 08 - Calculate Asset Final Risk  (FÓRMULA v4)
//
//   H = 1 si criticality_overridden === true, si no H = 0
//   ContextFactor = 0.20*(1+H)*Criticality_norm
//                 + 0.20*(1-H)*ModuleSensitivity_norm
//                 + 0.30*Exposure_norm
//                 + 0.30*BlastRadius_norm
//   FinalRisk = TechnicalRisk * (1 + ContextFactor) / 2   -> [0,1]
//
//   Umbrales: CRITICAL >=0.80 / HIGH >=0.60 / MEDIUM >=0.40 / LOW <0.40
//
// El contexto se aplica aquí (nivel activo) y NO en el nodo 07,
// porque el contexto es propiedad del ACTIVO, no de la vulnerabilidad.
// ============================================================

function clamp(value, min = 0, max = 1) {
  const num = Number(value);
  if (!Number.isFinite(num)) return min;
  return Math.min(Math.max(num, min), max);
}

function toNumber(value, fallback = 0) {
  const num = Number(value);
  return Number.isFinite(num) ? num : fallback;
}

function toBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;
  const normalized = String(value ?? "").toLowerCase().trim();
  return ["true", "yes", "y", "1", "kev"].includes(normalized);
}

function riskLevel(score) {
  if (score >= 0.80) return "CRITICAL";
  if (score >= 0.60) return "HIGH";
  if (score >= 0.40) return "MEDIUM";
  return "LOW";
}

// --- Agrupación por activo ---
const items = $input.all().map(item => item.json);
const grouped = {};

for (const row of items) {
  const assetId = row.asset_id ?? "UNKNOWN_ASSET";

  if (!grouped[assetId]) {
    grouped[assetId] = {
      asset_id: row.asset_id,
      asset_name: row.asset_name,
      asset_type: row.asset_type,

      software: row.software,
      asset_version: row.asset_version,
      cpe_name: row.cpe_name,

      module_id: row.module_id,
      module_name: row.module_name,
      module_sensitivity_norm: toNumber(row.module_sensitivity_norm),

      exposure: row.exposure,
      exposure_norm: toNumber(row.exposure_norm),

      criticality: row.criticality,
      criticality_norm: toNumber(row.criticality_norm),

      blast_radius_norm: toNumber(row.blast_radius_norm, 0),
      blast_radius_status: row.blast_radius_status ?? "pending",

      criticality_overridden: row.criticality_overridden === true,
      criticality_override_level: row.criticality_override_level ?? null,

      cves: []
    };
  }

  if (row.cve_id !== "NO_CVE_FOUND") {
    grouped[assetId].cves.push({
      cve_id: row.cve_id,
      cvss_base_score: toNumber(row.cvss_base_score ?? row.cvss_score),
      cvss_base_severity: row.cvss_base_severity,
      cvss_norm: toNumber(row.cvss_norm),
      attack_vector: row.attack_vector,
      epss_score: toNumber(row.epss_score),
      epss_percentile: toNumber(row.epss_percentile),
      epss_norm: toNumber(row.epss_norm),
      kev_flag: toBoolean(row.kev_flag),
      kev_norm: toNumber(row.kev_norm),
      technical_risk: toNumber(row.technical_risk),
      nvd_description: row.nvd_description
    });
  }
}

const output = [];
const scoredAt = new Date().toISOString();

const SCORING_FORMULA =
  "ContextFactor=0.20*(1+H)*Criticality_norm+0.20*(1-H)*ModuleSensitivity_norm+0.30*Exposure_norm+0.30*BlastRadius_norm; FinalRisk=TechnicalRisk*(1+ContextFactor)/2; H=1 si criticality_overridden";

for (const asset of Object.values(grouped)) {
  const cves = asset.cves;

  // --- H binario: interruptor del override ---
  const H = asset.criticality_overridden === true ? 1 : 0;
  const contextMode = H === 1 ? "override" : "auto";

  const exposureNorm = clamp(asset.exposure_norm);
  const criticalityNorm = clamp(asset.criticality_norm);
  const moduleSensitivityNorm = clamp(asset.module_sensitivity_norm);
  const blastRadiusNorm = clamp(asset.blast_radius_norm);

  // --- ContextFactor unificado (pesos suman 1.0 para todo H) ---
  const contextFactor =
    0.20 * (1 + H) * criticalityNorm +
    0.20 * (1 - H) * moduleSensitivityNorm +
    0.30 * exposureNorm +
    0.30 * blastRadiusNorm;

  const contextFactorRounded = Number(contextFactor.toFixed(4));

  // --- Campos comunes a ambos casos ---
  const base = {
    asset_id: asset.asset_id,
    asset_name: asset.asset_name,
    asset_type: asset.asset_type,
    software: asset.software,
    asset_version: asset.asset_version,
    cpe_name: asset.cpe_name,
    module_id: asset.module_id,
    module_name: asset.module_name,

    exposure: asset.exposure,
    exposure_norm: Number(exposureNorm.toFixed(4)),
    criticality: asset.criticality,
    criticality_norm: Number(criticalityNorm.toFixed(4)),
    module_sensitivity_norm: Number(moduleSensitivityNorm.toFixed(4)),
    blast_radius_norm: Number(blastRadiusNorm.toFixed(4)),
    blast_radius_status: asset.blast_radius_status,

    criticality_overridden: asset.criticality_overridden,
    criticality_override_level: asset.criticality_override_level,
    h_flag: H,
    context_mode: contextMode,
    context_factor: contextFactorRounded,

    aggregation_method: "max technical_risk per asset, context applied once",
    scoring_model: "asset_final_risk_v4",
    scoring_formula: SCORING_FORMULA,

    phase: "baseline",
    pipeline_stage: "asset_final_risk_v4",
    is_latest: true,
    "@timestamp": scoredAt
  };

  // --- Caso: activo sin CVEs ---
  if (cves.length === 0) {
    output.push({
      json: {
        ...base,

        total_cves: 0,
        critical_cves: 0,
        high_cves: 0,
        kev_cves: 0,

        max_technical_risk: null,
        avg_technical_risk: null,

        final_risk_score: 0,
        risk_level: "INFO",

        top_cve_id: null,
        technical_risk: null,
        top_cve_cvss: null,
        top_cve_epss: null,
        top_cve_kev: false,

        asset_rationale: `No se identificaron CVEs asociadas al activo ${asset.asset_name}.`
      }
    });
    continue;
  }

  // --- Selección de la top CVE por TechnicalRisk ---
  const sortedByTechnicalRisk = [...cves].sort(
    (a, b) => b.technical_risk - a.technical_risk
  );
  const topCve = sortedByTechnicalRisk[0];

  const maxTechnicalRisk = topCve.technical_risk;

  // --- FinalRisk: se contextualiza SOLO la top CVE ---
  const finalRiskRaw = maxTechnicalRisk * (1 + contextFactor) / 2;
  const finalRiskScore = Number(Math.min(finalRiskRaw, 1).toFixed(3));
  const finalRiskLevel = riskLevel(finalRiskScore);

  // --- Estadísticas de apoyo ---
  const kevCves = cves.filter(cve => cve.kev_flag === true).length;
  const criticalCves = cves.filter(cve => cve.cvss_base_score >= 9.0).length;
  const highCves = cves.filter(
    cve => cve.cvss_base_score >= 7.0 && cve.cvss_base_score < 9.0
  ).length;

  const avgTechnicalRisk =
    cves.reduce((sum, cve) => sum + toNumber(cve.technical_risk), 0) / cves.length;

  output.push({
    json: {
      ...base,

      total_cves: cves.length,
      critical_cves: criticalCves,
      high_cves: highCves,
      kev_cves: kevCves,

      max_technical_risk: Number(maxTechnicalRisk.toFixed(4)),
      avg_technical_risk: Number(avgTechnicalRisk.toFixed(4)),

      final_risk_score: finalRiskScore,
      risk_level: finalRiskLevel,

      top_cve_id: topCve.cve_id,
      technical_risk: Number(maxTechnicalRisk.toFixed(4)),
      top_cve_cvss: topCve.cvss_base_score,
      top_cve_epss: topCve.epss_score,
      top_cve_kev: topCve.kev_flag,

      asset_rationale: `El activo ${asset.asset_name} (${asset.exposure}, criticidad ${asset.criticality}) presenta ${cves.length} CVE(s). La de mayor riesgo técnico es ${topCve.cve_id} (TR ${maxTechnicalRisk.toFixed(3)}, CVSS ${topCve.cvss_base_score}, EPSS ${topCve.epss_score}${topCve.kev_flag ? ", en catálogo KEV" : ""}). Aplicando el contexto del activo (CF ${contextFactorRounded}, modo ${contextMode}), el riesgo final es ${finalRiskScore} → ${finalRiskLevel}.`
    }
  });
}

return output;

// Reemplaza: consulta EPSS + Merge + "05 add epss column"
const items = $input.all();

// IDs unicos de CVE, descartando los que no tienen
const cveIds = [...new Set(
  items.map(i => i.json.cve_id).filter(id => id && id !== 'NO_CVE_FOUND')
)];

// Una sola consulta _mget al indice local
const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://elasticsearch:9200/epss-scores/_mget',
  headers: { 'Content-Type': 'application/json' },
  body: { ids: cveIds },
  json: true,
});

// Mapa cve_id -> EPSS
const epssMap = {};
for (const d of resp.docs || []) {
  if (d.found) {
    epssMap[d._id] = {
      epss_score: d._source.epss_score,
      epss_percentile: d._source.epss_percentile,
    };
  }
}

// Enriquecer cada item
return items.map(item => {
  const row = item.json;
  const epss = epssMap[row.cve_id];
  const epssScore = epss ? Number(epss.epss_score) : 0;
  const epssPercentile = epss ? Number(epss.epss_percentile) : 0;

  return {
    json: {
      ...row,
      epss_score: Number(epssScore.toFixed(6)),
      epss_percentile: Number(epssPercentile.toFixed(6)),
      epss_source: "EPSS local index (epss-scores)",
      pipeline_stage: "epss_enriched",
      epss_enriched_at: new Date().toISOString()
    }
  };
});

// Lookup KEV desde el indice local, reemplaza query + merge
const items = $input.all();

const cveIds = [...new Set(
  items.map(i => i.json.cve_id).filter(id => id && id !== 'NO_CVE_FOUND')
)];

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://elasticsearch:9200/kev-catalog/_mget',
  headers: { 'Content-Type': 'application/json' },
  body: { ids: cveIds },
  json: true,
});

// Mapa cve_id -> datos KEV (solo los que estan en el catalogo)
const kevMap = {};
for (const d of resp.docs || []) {
  if (d.found) {
    kevMap[d._id] = d._source;
  }
}

return items.map(item => {
  const row = item.json;
  const kev = kevMap[row.cve_id];
  return {
    json: {
      ...row,
      kev_flag: !!kev,
      kev_date_added: kev ? (kev.dateAdded ?? kev.date_added ?? null) : null,
      kev_due_date: kev ? (kev.dueDate ?? kev.due_date ?? null) : null,
      kev_known_ransomware: kev ? (kev.knownRansomwareCampaignUse ?? kev.known_ransomware ?? null) : null,
      kev_source: "KEV local index (kev-catalog)",
      pipeline_stage: "kev_enriched"
    }
  };
});

// Recupera el documento de scoring del nodo 08 y le fusiona la remediacion de Claude
const scoringItems = $('08 -Final Risk Score- Asset').all();
const llmItems = $input.all();

return llmItems.map((llmItem, i) => {
  const scoring = scoringItems[i].json;   // el documento con todo el scoring

  // Extraer el texto que devolvio Claude
  let raw = (llmItem.json.text || llmItem.json.output || '').toString().trim();
  // Quitar fences ```json ... ```
  raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();

  let remediation;
  try {
    remediation = JSON.parse(raw);
  } catch (e) {
    remediation = {
      attack_technique: null,
      remediation_primary: null,
      remediation_compensating: null,
      priority_rationale: null,
      _remediation_error: `JSON parse failed: ${e.message}`
    };
  }

  return {
    json: {
      ...scoring,                    // TODO el scoring (asset_id, final_risk, @timestamp...)
      ...remediation,                // los 4 campos de Claude
      remediation_model: 'claude-sonnet-4-6',
      remediation_generated_at: new Date().toISOString()
    }
  };
});
